+          GITHUB_OUTPUT: out,
+          EVENT_NAME: 'issue_comment',
+          COMMENT_BODY: commentBody,
+          ISSUE_AUTHOR: author,
+          COMMENT_USER: commenter,
+          PR_NUMBER: '1',
+          TMUX_PR: '',
+        },
+        encoding: 'utf8',
+      });
+      const lines = readFileSync(out, 'utf8').trim().split('
');
+      return {
+        run: lines.filter((l) => l.startsWith('should_run=')).pop(),
